28	// assumption: "<assumption>. Accepted because <reason>." A marker inside a
29	// sentence ("Not accepted because") is not one (review round 3, N1).
30	var acceptedLimitMarkerRE = regexp.MustCompile(`[.;:!?]\s+(?:Accepted because|Aceito porque)\s+`)
31	
32	// acceptedLimitReasonWordRE is a word with at least one letter.
33	var acceptedLimitReasonWordRE = regexp.MustCompile(`\p{L}+`)
34	
35	// hasAcceptedLimitReason reads an entry as written: an assumption of at
36	// least two words, then the marker opening a sentence, then a reason of at
37	// least two words in that same sentence. A marker alone, punctuation, a
38	// missing assumption or a reason borrowed from a later sentence does not say
39	// why a limit is accepted (review rounds 1–4).
40	func hasAcceptedLimitReason(text string) bool {
41		loc := acceptedLimitMarkerRE.FindStringIndex(text)
42		if loc == nil {
43			return false
44		}
45		assumption, rest := text[:loc[0]], text[loc[1]:]
46		if end := strings.IndexAny(rest, ".;!?"); end >= 0 {
47			rest = rest[:end]
48		}
49		return len(acceptedLimitReasonWordRE.FindAllString(assumption, -1)) >= 2 && len(acceptedLimitReasonWordRE.FindAllString(rest, -1)) >= 2
50	}
51	
52	// ParseAcceptedLimits reads the `### Accepted limits` section of a spec body.
53	// It returns the limits and the problems that keep the section from being
54	// read as written: a bullet that is not `- L<N>: ...`, a repeated id, or a
55	// limit that does not say why it is accepted ("Accepted because ..." or
56	// "Aceito porque ...").
57	func ParseAcceptedLimits(body string) ([]ReviewAcceptedLimit, []string) {
58		var limits []ReviewAcceptedLimit
59		var problems []string
60		in := false
61		seen := map[string]bool{}
62		for _, line := range strings.Split(body, "\n") {
63			trimmed := strings.TrimSpace(line)
64			if strings.HasPrefix(trimmed, "#") {
65				in = strings.EqualFold(strings.TrimSpace(strings.TrimLeft(trimmed, "#")), "Accepted limits") || strings.EqualFold(strings.TrimSpace(strings.TrimLeft(trimmed, "#")), "Limites aceitos")
66				continue
67			}
68			if !in || !strings.HasPrefix(trimmed, "- ") {
69				continue
70			}
71			m := acceptedLimitRE.FindStringSubmatch(trimmed)
72			if m == nil {
73				problems = append(problems, "accepted limit "+quoteLedgerText(trimmed)+" is not written as '- L<N>: <assumption>. Accepted because <reason>.'")
74				continue
75			}
76			if seen[m[1]] {
77				problems = append(problems, "accepted limit "+m[1]+" is declared twice")
78				continue
79			}
80			seen[m[1]] = true
81			if !hasAcceptedLimitReason(m[2]) {
82				problems = append(problems, "accepted limit "+m[1]+" does not say why it is accepted ('Accepted because ...')")
83			}
84			limits = append(limits, ReviewAcceptedLimit{ID: m[1], Text: strings.TrimSpace(m[2])})
85		}
86		return limits, problems
87	}
