89	// acceptedLimitsOf collects the limits the scope's specs declare.
90	func (s Store) acceptedLimitsOf(scope ScopeRef) []ReviewAcceptedLimit {
91		specs, err := s.reviewScopeSpecs(scope)
92		if err != nil {
93			return nil
94		}
95		return acceptedLimitsOfSpecs(specs)
96	}
97	
98	// acceptedLimitsOfSpecs collects the limits specs declare, qualifying each id
99	// by its spec when there is more than one spec.
100	func acceptedLimitsOfSpecs(specs []Spec) []ReviewAcceptedLimit {
101		var out []ReviewAcceptedLimit
102		for _, spec := range specs {
103			limits, _ := ParseAcceptedLimits(spec.Body)
104			for _, l := range limits {
105				// Ids are spec-local: across specs each is qualified by its spec,
106				// so a finding names exactly one sealed limit.
107				if len(specs) > 1 {
108					l.ID, l.Spec = spec.Slug+"#"+l.ID, spec.Slug
109				}
110				out = append(out, l)
111			}
112		}
113		return out
114	}
