116	// sealedAcceptedLimit reports whether the bundle sealed limit id.
117	func sealedAcceptedLimit(bundle ReviewBundle, id string) bool {
118		for _, l := range bundle.Payload.Plan.AcceptedLimits {
119			if l.ID == id {
120				return true
121			}
122		}
123		return false
124	}
