15	func (s Store) sealReadinessBlockers(bundle ReviewBundle) []string {
16		scope, err := ParseScopeRef(bundle.Payload.Scope.Ref)
17		if err != nil || scope.Kind != "spec" {
18			return nil
19		}
20		var blockers []string
21		// R1: the declarations `pose close` requires, read from the same index
22		// findings its delivery assurance gate reports.
23		{
24			if graph, err := s.GetDeliveryIntegrity(""); err == nil {
25				for _, finding := range graph.Findings {
26					if !sealReadinessFindingCodes[finding.Code] || finding.Spec != scope.Slug || finding.Severity != "error" && finding.Severity != "critical" {
27						continue
28					}
29					msg := finding.Code + " [" + finding.Path + "]: " + finding.Message
30					if finding.Remediation != "" {
31						msg += " (" + finding.Remediation + ")"
32					}
33					blockers = append(blockers, msg+"; pose close refuses it after the review")
34				}
35			}
36		}
37		// R2: a structural fact is mapped to a decision basis, and the preflight
38		// refuses a basis that reaches no requirement or constraint. When the plan
39		// asks for mappings, every declared decision must be usable as one.
40		asksMapping := false
41		for _, criterion := range bundle.Payload.Plan.Criteria {
42			asksMapping = asksMapping || criterion.Required && criterion.RequiresStructuralMapping
43		}
44		if structure := bundle.Payload.Plan.Structure; asksMapping && structure != nil && len(structure.Material) > 0 {
45			ns := s.reviewDesignBasisNamespace(scope)
46			var unreached []string
47			for id := range ns.Known {
48				if !ns.Reaches[id] {
49					unreached = append(unreached, id)
50				}
51			}
52			sort.Strings(unreached)
53			for _, id := range unreached {
54				blockers = append(blockers, "decision basis "+id+" reaches no requirement or constraint: give it a `- Basis:` line naming one, or the conclusion preflight refuses a mapping to it")
55			}
56		}
57		return uniqueSorted(blockers)
58	}
