288		order := map[string]int{"required": 0, "recommended": 1, "completion-deferred": 2}
289		sort.SliceStable(result, func(i, j int) bool {
290			if order[result[i].Phase] != order[result[j].Phase] {
291				return order[result[i].Phase] < order[result[j].Phase]
292			}
293			return result[i].Tool.ID < result[j].Tool.ID
294		})
295		return result
